/* =====================================================
   参考图精修 v3：按用户提供的 iPod 播放器截图调整
   重点：屏幕缩短并下移、专辑封面缩小并靠左、顶部银灰标题条
   保留原有机身素材、转盘、页面控制按钮和交互选择器
   ===================================================== */

/* iPod 机身比例保持原素材，不改变转盘和外壳 */
.vinyl-disc {
  width: 208px !important;
  height: 330px !important;
  background-size: 100% 100% !important;
  filter:
    drop-shadow(0 1px 0 rgba(255, 255, 255, 0.55))
    drop-shadow(0 18px 17px rgba(35, 37, 44, 0.30)) !important;
}

/* 屏幕按参考图调整：约占机身高度 37%，顶部留白更明显 */
.vinyl-disc::before {
  left: 10.5% !important;
  right: 10.5% !important;
  top: 7.2% !important;
  height: 36.8% !important;
  padding: 3px 0 0 8px !important;
  border: 2px solid #343b49 !important;
  border-radius: 6px !important;
  font: 700 10px/14px "Helvetica Neue", Helvetica, Arial, sans-serif !important;
  background-size: 30px 9px, 100% 100% !important;
  background-position: right 7px top 6px, 0 0 !important;
  background-image:
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 30 9'><path d='M1 0l8 4.5-8 4.5z' fill='%232a8bf2'/><rect x='19' y='1' width='9' height='7' rx='1' fill='%2341c15a' stroke='%23666' stroke-width='.7'/><rect x='28' y='3' width='1.5' height='3' fill='%23666'/></svg>"),
    linear-gradient(180deg, #edf0f2 0, #cbd1d6 7px, #aeb5bc 14px, #8c939a 15px, #ffffff 15px, #ffffff 100%) !important;
}
.is-playing .vinyl-disc::before {
  background-image:
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 30 9'><path d='M1 0l8 4.5-8 4.5z' fill='%232a8bf2'/><rect x='19' y='1' width='9' height='7' rx='1' fill='%2341c15a' stroke='%23666' stroke-width='.7'/><rect x='28' y='3' width='1.5' height='3' fill='%23666'/></svg>"),
    linear-gradient(180deg, #edf0f2 0, #cbd1d6 7px, #aeb5bc 14px, #8c939a 15px, #ffffff 15px, #ffffff 100%) !important;
}

/* 专辑封面：参考图中位于屏幕左侧，尺寸约为屏幕宽度的 38% */
.circular-img {
  top: 48px !important;
  left: 15% !important;
  right: auto !important;
