/* =====================================================
   v5 重写：标题栏不再溢出 + 歌名/歌手真正写进 iPod 屏幕
   ---------------------------------------------------
   为什么 v4 不显示：歌名/歌手元素在 iPod 外面，
   写成 ".vinyl-disc .rp-song-title" 永远匹配不到。
   这版改成：iPod 和歌名/歌手都按「屏幕坐标」定位，
   位置关系由下面几个变量统一控制，想挪只改这里。
   ===================================================== */
:root {
  --ipod-top: 24vh;      /* iPod 顶部离屏幕顶部的距离（整体上下移动改这个）*/
  --stage-top: 234px;    /* ★ 舞台顶部离屏幕顶部的距离（按「一起听」显示时实测）。
                            iPod 在舞台里面，定位是从舞台顶部算起的，所以要减掉它。
                            iPod 跑得太靠下就调大，太靠上就调小 */
}

/* 让 iPod 所在层级低于歌名/歌手，避免文字被机身盖住 */
.rp-stage {
  position: relative !important;
  z-index: 0 !important;
}

/* iPod 钉在屏幕坐标里（水平居中），不再依赖原来的舞台布局 */
.vinyl-disc {
  position: fixed !important;
  top: calc(var(--ipod-top) - var(--stage-top)) !important;
  left: 50% !important;
  right: auto !important;
  bottom: auto !important;
  margin: 0 0 0 -104px !important;
  z-index: 0 !important;
}

/* ---------- 标题栏：整条用图片画，文字画在 SVG 里，永远不会溢出 ---------- */
.vinyl-disc::before,
.is-playing .vinyl-disc::before {
  content: "" !important;
  padding: 0 !important;
  overflow: hidden !important;
  white-space: nowrap !important;
  background-origin: border-box !important;
  background-repeat: no-repeat !important;
  background-size: 164px 17px, 100% 100% !important;
  background-position: 0 0, 0 0 !important;
}
/* 暂停：Pause + 蓝色暂停条 + 电池 */
.vinyl-disc::before {
  background-image:
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 164 17' preserveAspectRatio='xMinYMin meet'><text x='9' y='12' font-family='Helvetica Neue,Helvetica,Arial,sans-serif' font-size='9.5' font-weight='700' fill='%2314171c'>Pause</text><rect x='118' y='4.5' width='2.6' height='8' fill='%232a8bf2'/><rect x='122.4' y='4.5' width='2.6' height='8' fill='%232a8bf2'/><rect x='134' y='4.5' width='16' height='8' rx='1.6' fill='%2341c15a' stroke='%23666' stroke-width='.8'/><rect x='150.8' y='7' width='1.6' height='3' fill='%23666'/></svg>"),
    linear-gradient(180deg, #edf0f2 0, #cbd1d6 8px, #aeb5bc 16px, #8c939a 16px, #8c939a 17px, #ffffff 17px, #ffffff 100%) !important;
}
/* 播放：Now Playing + 蓝色播放三角 + 电池 */
.is-playing .vinyl-disc::before {
  background-image:
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 164 17' preserveAspectRatio='xMinYMin meet'><text x='9' y='12' font-family='Helvetica Neue,Helvetica,Arial,sans-serif' font-size='9.5' font-weight='700' fill='%2314171c'>Now Playing</text><path d='M118 4.5l7 4-7 4z' fill='%232a8bf2'/><rect x='134' y='4.5' width='16' height='8' rx='1.6' fill='%2341c15a' stroke='%23666' stroke-width='.8'/><rect x='150.8' y='7' width='1.6' height='3' fill='%23666'/></svg>"),
    linear-gradient(180deg, #edf0f2 0, #cbd1d6 8px, #aeb5bc 16px, #8c939a 16px, #8c939a 17px, #ffffff 17px, #ffffff 100%) !important;
}

/* ---------- 封面：屏幕左侧，Cover Flow 斜放 + 倒影 ---------- */
.vinyl-disc .circular-img {
  position: absolute !important;
  top: 48px !important;
  left: 15% !important;
  right: auto !important;
  bottom: auto !important;
  width: 62px !important;
  height: 66px !important;
  margin: 0 !important;
  transform: perspective(260px) rotateY(32deg) !important;
  transform-origin: 50% 50% !important;
  z-index: 6 !important;
}

data.css:
* { margin: 0; padding: 0; box-sizing: border-box; }
html, body { width: 100%; height: 100%; overflow: hidden; }
body { font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif; }

.widget {
  position: relative;
  width: 100%; height: 100%;
  border-radius: 24px;
  overflow: hidden;
  display: flex; flex-direction: column; justify-content: space-between;
  padding: 12px 14px;
}

.bg-layer {
  position: absolute; inset: 0;
  background-image: url({{bgImage}});
  background-size: cover;
  background-position: center;
  z-index: 0;
}
.bg-tint {
  position: absolute; inset: 0;
  z-index: 1;
  transition: background .3s ease;
}

.top-row { position: relative; z-index: 2; display: flex; align-items: center; gap: 8px; }
.avatar { border-radius: 50%; object-fit: cover; background: #ddd; }
.avatar-left { width: 34px; height: 34px; box-shadow: 0 2px 6px rgba(0,0,0,0.15); }
.label-left { font-size: 13px; font-weight: 600; color: #fff; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.center-col { position: relative; z-index: 2; display: flex; flex-direction: column; align-items: center; gap: 3px; }
.time { font-size: 28px; font-weight: 800; color: #fff; letter-spacing: 1px; line-height: 1; }
.quote { font-size: 11px; color: rgba(255,255,255,0.85); }

.bottom-row {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: flex-end;
}
.pill {
  background: rgba(255,255,255,0.85);
  border-radius: 999px;
  padding: 6px 14px;
  margin-right: 8px;
  overflow: hidden;
}
.label-pill { font-size: 11px; font-weight: 600; color: #333; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.avatar-right {
  width: 34px; height: 34px;
  flex-shrink: 0;
  box-shadow: 0 2px 6px rgba(0,0,0,0.15);
}
/*⁣‌⁠​‍‌‌⁠‍​​​‌⁠​‍⁠‍‌‌​‌‌‌⁠‍‌‌‌​⁠⁠‍‍‍⁠⁠‌‌⁠‍‍‌⁠‍​‌‌⁠‍‌​​⁠⁠⁠⁠‍​⁠​‍‌​⁠⁣*/

.mz-cat-clock, .mz-cat-clock * {
  -webkit-tap-highlight-color: transparent !important;
  -webkit-user-select: none !important;
  user-select: none !important;
  outline: none !important;
}

.mz-cat-clock {
  container-type: inline-size;
  width: 100%; height: 100%; position: relative;
  font-family: "PingFang SC", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  box-sizing: border-box; overflow: hidden;
  border-radius: clamp(16px, 6cqw, 24px);
  background: var(--bg-clock); 
  display: flex; align-items: center; justify-content: center;
}

.clock-container {
  position: relative; 
  width: 100%; height: 100%;
  display: flex; align-items: center; justify-content: center;
}

.cat-face {
  position: relative;
  display: flex; align-items: center; justify-content: center;
  padding: clamp(10px, 3cqw, 20px) clamp(30px, 8cqw, 60px); 
}

.time-text {
  margin-top: clamp(15px, 5cqw, 30px);
  font-size: var(--s-time);
  /*⁣‌⁠​‍‌‌⁠‍​​​‌⁠​‍⁠‍‌‌​‌‌‌⁠‍‌‌‌​⁠⁠‍‍‍⁠⁠‌‌⁠‍‍‌⁠‍​‌‌⁠‍‌​​⁠⁠⁠⁠‍​⁠​‍‌​⁠⁣ 直接锁定最标准的粗体，告别多层阴影带来的重影问题 */
  font-weight: 700;
  color: var(--c-time);
  letter-spacing: clamp(1px, 0.5cqw, 4px);
  line-height: 1;
  position: relative;
  z-index: 5;
  display: flex; align-items: center;
}

.colon {
  margin: 0 clamp(4px, 1cqw, 8px);
  opacity: 1; 
  padding-bottom: clamp(6px, 1.5cqw, 10px); 
}

/* =========================================
   🐾 SVG 定位 
========================================= */
.svg-icon { position: absolute; z-index: 10; }
.svg-icon svg { overflow: visible !important; }

.ear-outline { stroke: var(--c-ear); }
.ear-inner { fill: var(--c-ear); stroke: var(--c-ear); }
.whisker-left svg, .whisker-right svg { stroke: var(--c-whisker); }

.ear-left {
  width: clamp(55px, 16cqw, 90px); height: clamp(55px, 16cqw, 90px);
  top: clamp(-30px, -8cqw, -55px);
  left: clamp(-5px, -1cqw, -15px);
  transform: rotate(-10deg);
}
.ear-right {
  width: clamp(55px, 16cqw, 90px); height: clamp(55px, 16cqw, 90px);
  top: clamp(-30px, -8cqw, -55px);
  right: clamp(-5px, -1cqw, -15px);
  transform: rotate(10deg);
}

.whisker-left {
