/* ============================================================
   🌊 二次元小清新（Anime Fresh）
   ------------------------------------------------------------
   ① 換自己的素材：把下面的 none 換成圖片
      —— 點編輯框上方「＋ 插入圖片」選圖，會自動貼成 url('...')，
         把它填進對應那一行即可（存檔後自動落檔，離線也在）。
   ② 換文案：直接改引號裡的字。沒放圖的位置會用內建花紋頂著。
   ============================================================ */
:root {
    /* ▼▼▼ 你的素材（換這幾行就行）▼▼▼ */
    --art-bg: none;            /* 整頁背景大圖 */
    --art-char-right: none;    /* 右側立繪（大張，露在日曆右邊） */
    --art-char-left: none;     /* 左上角淡淡的第二張立繪 */
    --art-photo: none;         /* 大拍立得裡的照片 */
    --art-photo-2: none;       /* 日曆右側小相片 */
    --art-sticker: none;       /* 右下角小貼紙（沒放圖時顯示 🩹） */
    --quote: '喜歡你，是我的超能力';   /* 大拍立得下方手寫句 */
    --quote-sub: '今天也要閃閃發光哦'; /* 日曆下方手寫句 */
    --quote-memo: 'have a nice day ♡'; /* 日曆右上便條的字 */
    --art-event-icon: none;    /* 行程塊左側小圖（沒放圖時顯示內建星星） */
    /* ▲▲▲ 素材結束 ▲▲▲ */

    --hand: 'Comic Sans MS', 'Chalkboard SE', 'Yu Gothic', 'PingFang TC', cursive;
    --sky: #dcefff;
    --sky-deep: #6bb2df;
    --ink-blue: #5b7a94;
    --pink: #ff9fb2;
    --glow: rgba(150, 205, 245, 0.55);
    /* 沒放照片時墊底的藍色菱格紋 */
    --lattice: repeating-linear-gradient(45deg, rgba(120, 180, 230, 0.35) 0 1px, transparent 1px 14px),
               repeating-linear-gradient(-45deg, rgba(120, 180, 230, 0.35) 0 1px, transparent 1px 14px),
               linear-gradient(135deg, #cfe6fb, #e6f3ff);

    /* ── 全局 ── */
    --cal-page-bg: linear-gradient(180deg, #eaf5ff 0%, #f4fbff 45%, #fdfdf3 100%);
    --cal-page-bg-image: var(--art-bg);
    --cal-page-bg-size: cover;
    --cal-page-bg-position: center top;
    --cal-ink: var(--ink-blue);
    --cal-ink-muted: #9cc3dc;
    --cal-accent: var(--sky-deep);
    --cal-page-padding: max(var(--nuo-safe-top), 20px) 18px 120px;

    /* ── 月份標題：左上，大號細體淺藍 ── */
    --cal-title-color: #b7dcf3;
    --cal-title-size: 2.6rem;
    --cal-title-weight: 300;
    --cal-title-letter-spacing: 2px;
    --cal-title-font: var(--hand);
    --cal-topbar-gap: 10px;

    --cal-avatar-size: 44px;
    --cal-avatar-border: 2px solid rgba(255, 255, 255, 0.9);
    --cal-avatar-shadow: 0 4px 14px rgba(120, 175, 215, 0.28);

    /* ── 星期列 ── */
    --cal-week-color: var(--sky-deep);
    --cal-week-size: 0.82rem;
    --cal-week-weight: 700;
    --cal-week-transform: uppercase;

    /* ── 日格：全透明 ── */
    --cal-grid-gap: 4px;
    --cal-grid-margin-bottom: 18px;
    --cal-day-bg: transparent;
    --cal-day-border: none;
    --cal-day-shadow: none;
    --cal-day-backdrop-filter: none;
    --cal-day-shine: transparent;
    --cal-day-width: 84%;
    --cal-day-height: 84%;
    --cal-daynum-color: #8aa6bd;
    --cal-daynum-size: 0.98rem;
    --cal-daynum-weight: 600;
    --cal-today-bg: var(--pink);
    --cal-today-radius: 50%;
    --cal-today-color: #fff;
    --cal-today-shadow: 0 4px 14px rgba(255, 159, 178, 0.5);
    --cal-selected-border: 2px solid rgba(255, 159, 178, 0.6);
    --cal-selected-transform: none;
    --cal-selected-shadow: none;
    --cal-dot-color: #a9d8f5;

    /* ── 今日卡片：發光藍玻璃 ── */
    --cal-card-bg: rgba(226, 243, 255, 0.55);
    --cal-card-radius: 22px;
    --cal-card-border: 1px solid rgba(255, 255, 255, 0.85);
    --cal-card-shadow: 0 0 0 6px rgba(200, 230, 255, 0.35), 0 10px 30px rgba(120, 175, 215, 0.18);
    --cal-card-backdrop-filter: blur(14px);
    --cal-card-padding: 18px 16px 18px;
    --cal-card-title-color: var(--ink-blue);
    --cal-card-title-size: 1rem;
    --cal-item-radius: 16px;
    --cal-item-padding: 12px 14px;
    --cal-item-border: 1px solid rgba(255, 255, 255, 0.8);
    --cal-item-shadow: 0 0 18px var(--glow);
    --cal-item-user-bg: rgba(198, 232, 255, 0.72);
    --cal-item-ai-bg: rgba(255, 246, 214, 0.68);
    --cal-item-todo-bg: rgba(214, 244, 226, 0.68);
    --cal-item-header-color: #6d90ab;
    --cal-item-text-color: #4d6d86;

    /* ── 底欄：懸浮藥丸 ── */
    --cal-nav-bg: rgba(255, 255, 255, 0.72);
    --cal-nav-radius: 32px;
    --cal-nav-border: 1px solid rgba(255, 255, 255, 0.85);
    --cal-nav-shadow: 0 10px 30px rgba(120, 175, 215, 0.22);
    --cal-nav-backdrop-filter: blur(18px);
    --cal-nav-min-height: 0;
    --cal-nav-padding-top: 0;
    --cal-nav-color: #9db9cd;
    --cal-nav-active-color: #3f6f97;
    --cal-nav-active-transform: none;
    --cal-nav-label-size: 0.62rem;
    --cal-nav-label-weight: 700;

    --cal-fab-bg: rgba(255, 255, 255, 0.92);
    --cal-fab-color: #5fa9dc;
    --cal-fab-size: 48px;
    --cal-fab-radius: 50%;
    --cal-fab-border: 2px solid rgba(140, 200, 240, 0.7);
    --cal-fab-shadow: 0 0 0 6px rgba(206, 234, 255, 0.55), 0 8px 20px rgba(120, 175, 215, 0.3);

    --cal-sticker-size: 18px;
    --cal-sticker-border: 2px solid rgba(255, 255, 255, 0.95);
    --cal-sticker-marker-bg: linear-gradient(135deg, #fff7d6, #ffe9a8);
    --cal-sticker-heart-bg: linear-gradient(135deg, #ffe3ea, #ffc2cf);

    /* ── 彈層 ── */
    --cal-overlay-bg: rgba(190, 220, 240, 0.35);
    --cal-overlay-backdrop-filter: blur(10px);
    --cal-modal-bg: rgba(255, 255, 255, 0.9);
    --cal-modal-radius: 26px;
    --cal-modal-border: 1px solid rgba(255, 255, 255, 0.9);
    --cal-modal-shadow: 0 18px 46px rgba(110, 165, 205, 0.28);
    --cal-menu-bg: rgba(255, 255, 255, 0.92);
    --cal-menu-radius: 22px;
    --cal-menu-shadow: 0 12px 34px rgba(120, 175, 215, 0.26);
    --cal-menu-item-color: var(--ink-blue);
    --cal-vcal-bg: rgba(226, 243, 255, 0.6);
    --cal-vcal-border: 1px solid rgba(255, 255, 255, 0.85);
    --cal-vcal-label-color: var(--ink-blue);
    --cal-vcal-sub-color: #8fb6cf;
    --cal-tag-radius: 8px;
    --cal-tag-border: 1px solid rgba(255, 255, 255, 0.8);

    /* ── 行程表 ── */
    --cal-section-title-color: #a9d3ef;
    --cal-section-title-size: 1.5rem;
    --cal-section-title-weight: 400;
    --cal-now-pill-bg: rgba(255, 255, 255, 0.9);
    --cal-now-pill-color: var(--pink);
    --cal-now-pill-border: 2px solid rgba(255, 159, 178, 0.55);
    --cal-now-pill-radius: 20px;
    --cal-char-avatar-size: 72px;
    --cal-char-avatar-radius: 18px;
    --cal-char-avatar-border: 3px solid rgba(255, 255, 255, 0.95);
    --cal-char-avatar-shadow: 0 8px 24px rgba(120, 175, 215, 0.3);
    --cal-tl-header-color: var(--ink-blue);
    --cal-bubble-radius: 18px;
    --cal-bubble-border-color: transparent;
    --cal-bubble-shadow: 0 0 0 8px rgba(200, 230, 255, 0.45), 0 0 28px var(--glow);
    --cal-bubble-title-color: #4d6d86;
    --cal-bubble-sub-color: #7fa2ba;
    --cal-agenda-bg: rgba(198, 232, 255, 0.62);
    --cal-agenda-color: #4d6d86;
    --cal-agenda-radius: 18px;
    --cal-agenda-shadow: 0 0 0 8px rgba(200, 230, 255, 0.45), 0 0 24px var(--glow);
    --cal-stat-header-bg: transparent;
    --cal-stat-header-radius: 0;
    --cal-stat-header-backdrop-filter: none;
    --cal-stat-name-color: var(--ink-blue);
    --cal-stat-label-color: #8fb6cf;
    --cal-stat-bar-bg: rgba(255, 255, 255, 0.7);
    --cal-stat-bar-fill: #a9d8f5;
    --cal-stat-avatar-bg: rgba(255, 255, 255, 0.95);
    --cal-stat-avatar-radius: 18px;

    /* ── 待辦 ── */
    --cal-todo-panel-bg: rgba(255, 255, 255, 0.85);
    --cal-todo-panel-radius: 28px 28px 0 0;
    --cal-todo-panel-shadow: 0 -10px 30px rgba(120, 175, 215, 0.18);
    --cal-todo-radius: 16px;
    --cal-todo-text-color: #4d6d86;
    --cal-todo-check-border: 2px solid rgba(110, 165, 205, 0.5);
    --cal-todo-check-radius: 8px;
    --cal-todo-check-color: var(--sky-deep);

    /* ── 共鳴影集 ── */
    --cal-memory-bg: transparent;
    --cal-memory-title-bg: rgba(255, 255, 255, 0.92);
    --cal-memory-title-color: var(--sky-deep);
    --cal-memory-title-border: none;
    --cal-memory-title-radius: 4px;
    --cal-memory-title-shadow: 0 6px 18px rgba(120, 175, 215, 0.25);
    --cal-memory-title-rotate: rotate(-3deg);
    --cal-report-bg: rgba(226, 243, 255, 0.55);
    --cal-report-border: 1px solid rgba(255, 255, 255, 0.9);
    --cal-report-radius: 22px;
    --cal-report-shadow: 0 0 0 8px rgba(200, 230, 255, 0.35), 0 12px 30px rgba(120, 175, 215, 0.18);
    --cal-report-title-color: var(--ink-blue);
    --cal-polaroid-bg: #fff;
    --cal-polaroid-border: none;
    --cal-polaroid-radius: 3px;
    --cal-polaroid-padding: 10px 10px 34px;
    --cal-polaroid-shadow: 0 8px 22px rgba(120, 175, 215, 0.22);
    --cal-polaroid-img-bg: #eaf4fb;
    --cal-polaroid-caption-color: var(--sky-deep);
    --cal-polaroid-caption-font: var(--hand);
    --cal-badge-name-color: #7fa2ba;
    --cal-badge-avatar-border: 3px solid rgba(255, 255, 255, 0.95);
    --cal-letter-bg: rgba(255, 255, 255, 0.9);
    --cal-letter-border: 1px solid rgba(180, 215, 240, 0.5);
}

/* ================= 月視圖版面 ================= */
.nuo-cal-title-wrap {
    position: static;
    transform: none;
    justify-content: flex-start;
    margin-right: auto;
}

.nuo-cal-topbar {
    align-items: center;
    gap: 12px;
}

.nuo-cal-topbar .back-icon {
    width: 36px;
    height: 36px;
    padding: 7px;
    box-sizing: border-box;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.85);
    color: #6bb2df;
    box-shadow: 0 4px 12px rgba(120, 175, 215, 0.25);
    flex-shrink: 0;
}

.nuo-cal-title-wrap {
    min-width: 0;
}

.nuo-cal-weekbar,
.nuo-cal-grid {
    width: 64%;
    min-width: 236px;
}

.nuo-cal-cell[data-dow='0'] .day-number,
.nuo-cal-cell[data-dow='6'] .day-number {
    color: #7cbdea;
}

.nuo-cal-month {
    position: relative;
    z-index: 1;
}

/* ---- 大拍立得（星期列上方）---- */
.nuo-cal-decor-grid-top {
    display: block;
    position: relative;
    width: 60%;
    min-width: 226px;
    margin: 6px 0 20px 4px;
    padding: 10px 10px 34px;
    background: #fff;
    border-radius: 3px;
    box-shadow: 0 10px 26px rgba(120, 175, 215, 0.25);
    transform: rotate(-2deg);
    z-index: 1;
}

.nuo-cal-decor-grid-top::before {
    content: '';
    display: block;
    aspect-ratio: 1 / 0.92;
    border-radius: 2px;
    background: var(--art-photo) center / cover no-repeat, var(--lattice);
}

.nuo-cal-decor-grid-top::after {
    content: var(--quote);
    position: absolute;
    left: 0;
    right: 0;
    bottom: 9px;
    text-align: center;
    font-family: var(--hand);
    font-size: 0.82rem;
    letter-spacing: 1px;
    color: #8fc6e8;
}

/* 拍立得右側：便條卡（虛線框 + 手寫字）—— 掛在月曆頂欄上，別的分頁不會出現 */
.nuo-cal-topbar::after {
    content: var(--quote-memo);
    position: absolute;
    right: 4px;
    top: 74px;
    width: 32%;
    min-width: 108px;
    padding: 12px 10px 30px;
    box-sizing: border-box;
    background:
        radial-gradient(circle at 20% 92%, rgba(169, 216, 245, 0.9) 0 2px, transparent 3px),
        radial-gradient(circle at 50% 92%, rgba(169, 216, 245, 0.9) 0 2px, transparent 3px),
        radial-gradient(circle at 80% 92%, rgba(169, 216, 245, 0.9) 0 2px, transparent 3px),
        rgba(255, 255, 255, 0.85);
    border: 2px dashed rgba(140, 200, 240, 0.65);
    border-radius: 10px;
    box-shadow: 0 8px 22px rgba(120, 175, 215, 0.2);
    transform: rotate(4deg);
    font-family: var(--hand);
    font-size: 0.86rem;
    line-height: 1.5;
    letter-spacing: 1px;
    color: #7fb8de;
    text-align: center;
    pointer-events: none;
    z-index: 1;
}

/* 便條上方壓一條紙膠帶 */
.nuo-cal-topbar::before {
    content: '';
    position: absolute;
    right: 22px;
    top: 64px;
    width: 54px;
    height: 16px;
    background: rgba(170, 215, 245, 0.8);
    background-image: repeating-linear-gradient(-45deg, rgba(255, 255, 255, 0.55) 0 4px, transparent 4px 8px);
    transform: rotate(-6deg);
    border-radius: 2px;
    z-index: 2;
    pointer-events: none;
}

.nuo-cal-topbar {
    overflow: visible;
}

/* 拍立得右上角的迴紋針 */
.nuo-cal-decor-topbar {
    display: block;
    position: absolute;
    left: min(58%, 250px);
    top: 78px;
    font-size: 1.6rem;
    transform: rotate(35deg);
    opacity: 0.85;
    pointer-events: none;
    z-index: 2;
}

.nuo-cal-decor-topbar::before {
    content: '📎';
}

/* ---- 日曆右側那一欄：小相片 + 貼紙 + 星星 ---- */
.nuo-cal-grid {
    position: relative;
}

/* 小相片卡（放在日曆右邊，帶藍色虛線框） */
.nuo-cal-grid::after {
    content: '';
    position: absolute;
    left: 108%;
    top: -12px;
    width: 46%;
    aspect-ratio: 1 / 1.05;
    padding: 8px;
    box-sizing: border-box;
    background: var(--art-photo-2) center / cover no-repeat padding-box, #fff;
    border: 2px dashed rgba(140, 200, 240, 0.7);
    border-radius: 6px;
    box-shadow: 0 8px 22px rgba(120, 175, 215, 0.22), inset 0 0 0 8px #fff;
    transform: rotate(3deg);
    background-image: var(--art-photo-2), var(--lattice);
    background-clip: padding-box;
    pointer-events: none;
}

/* 星星點綴（右欄上方） */
.nuo-cal-grid::before {
    content: '✦  ✦  ✦';
    position: absolute;
    left: 112%;
    bottom: 6px;
    font-size: 1.1rem;
    line-height: 1.6;
    color: #9fd0f0;
    opacity: 0.8;
    pointer-events: none;
}

/* 貼紙：有圖用圖，沒圖用 🩹 */
.nuo-cal-decor-float-br {
    display: block;
    position: fixed;
    left: 14px;
    bottom: 92px;
    width: 64px;
    height: 64px;
    background: var(--art-sticker) center / contain no-repeat;
    font-size: 2.2rem;
    line-height: 64px;
    text-align: center;
    transform: rotate(-18deg);
    pointer-events: none;
    z-index: 2;
}

.nuo-cal-decor-float-br::before {
    content: '🩹';
    opacity: 0.9;
}

/* 右側大立繪（放圖後才會出現） */
.nuo-cal-decor-float-tr {
    display: block;
    position: fixed;
    right: -0.5vw;
    bottom: 92px;
    width: 46vw;
    height: 62vh;
    background: var(--art-char-right) right bottom / contain no-repeat;
    pointer-events: none;
    z-index: 0;
}

/* 左上第二張淡立繪 */
.nuo-cal-decor-float-tl {
    display: block;
    position: fixed;
    inset: 0;
    background: var(--art-char-left) left 60px / 42vw auto no-repeat;
    opacity: 1;
    pointer-events: none;
    z-index: 1;
}

/* 星星水印撒滿全頁 */
.nuo-cal-decor-watermark {
    display: block;
    position: fixed;
    inset: 0;
    background:
        radial-gradient(circle at 12% 18%, rgba(160, 210, 245, 0.35) 0 3px, transparent 4px),
        radial-gradient(circle at 78% 30%, rgba(160, 210, 245, 0.3) 0 2px, transparent 3px),
        radial-gradient(circle at 30% 66%, rgba(160, 210, 245, 0.3) 0 2px, transparent 3px),
        radial-gradient(circle at 88% 74%, rgba(160, 210, 245, 0.35) 0 3px, transparent 4px),
        radial-gradient(circle at 55% 88%, rgba(160, 210, 245, 0.25) 0 2px, transparent 3px);
    pointer-events: none;
    z-index: 0;
}

/* 日曆下方手寫句 */
.nuo-cal-decor-grid-bottom {
    display: block;
    margin: -6px 0 14px 6px;
    font-family: var(--hand);
    font-size: 0.95rem;
    letter-spacing: 2px;
    color: #9ecbe8;
}

.nuo-cal-decor-grid-bottom::before {
    content: var(--quote-sub);
}

/* 今日卡片四角的小括弧裝飾（圖二那種相框感） */
.nuo-cal-card {
    position: relative;
}

.nuo-cal-decor-card-top {
    display: block;
    position: absolute;
    inset: 6px;
    pointer-events: none;
    border-radius: 18px;
    background:
        radial-gradient(circle at 0 0, transparent 9px, rgba(140, 200, 240, 0.55) 10px, transparent 12px) top left / 22px 22px no-repeat,
        radial-gradient(circle at 100% 0, transparent 9px, rgba(140, 200, 240, 0.55) 10px, transparent 12px) top right / 22px 22px no-repeat,
        radial-gradient(circle at 0 100%, transparent 9px, rgba(140, 200, 240, 0.55) 10px, transparent 12px) bottom left / 22px 22px no-repeat,
        radial-gradient(circle at 100% 100%, transparent 9px, rgba(140, 200, 240, 0.55) 10px, transparent 12px) bottom right / 22px 22px no-repeat;
}

/* ================= 底欄：懸浮藥丸 + 右下獨立加號 ================= */
.calendar-bottom-nav {
    left: 14px;
    right: 14px;
    bottom: max(14px, var(--nuo-safe-bottom));
    padding: 8px 10px;
    padding-bottom: 8px;
    align-items: center;
}

.nav-btn {
    padding: 6px 10px;
    border-radius: 22px;
    transition: background 0.2s ease;
}

.nav-btn.active {
    background: rgba(226, 243, 255, 0.9);
}

.nav-btn-add {
    position: fixed;
    right: 16px;
    bottom: 92px;
    width: 48px;
    height: 48px;
    z-index: 101;
}

.add-button {
    margin-top: 0;
}

/* ================= 他們 / 我的：整頁改成「Schedule」手帳 ================= */
.nuo-cal-timeline,
.nuo-cal-memory {
    position: relative;
}

/* 手寫大標題 */
.section-title,
.timeline-header-title {
    font-family: var(--hand);
    letter-spacing: 2px;
    font-weight: 400;
}

.nuo-cal-timeline .section-title::after {
    content: '✦';
    margin-left: auto;
    font-size: 1.2rem;
    color: #9fd0f0;
}

/* 去掉時間軸：豎線、圓點、左側小時間全部收掉（時間標籤行內寫了 display:flex，要 !important） */
.nuo-cal-timeline .user-timeline-line,
.nuo-cal-timeline .timeline-vertical-line,
.nuo-cal-timeline .agenda-dot,
.nuo-cal-timeline .nuo-cal-time-label,
.nuo-cal-timeline .bubble-tail {
    display: none !important;
}

/* 日期標題：行內寫死的黑粗體改成手寫淡藍 */
.nuo-cal-timeline .section-title > span {
    font-family: var(--hand);
    font-weight: 400 !important;
    font-size: 1.35rem !important;
    letter-spacing: 2px;
    color: #7fb8de !important;
}

.nuo-cal-timeline .user-agenda-list {
    padding-left: 0;
    gap: 22px;
}

.nuo-cal-timeline .user-agenda-item {
    padding-left: 0;
}

/* 氣泡 → 通欄發光藍塊 */
.nuo-cal-timeline .timeline-bubble.modern-bubble {
    width: 100%;
    min-width: 0;
    background-color: rgba(198, 232, 255, 0.62);
    background-image: linear-gradient(135deg, rgba(255, 255, 255, 0.45), rgba(255, 255, 255, 0));
    border: none;
    margin: 8px 0;
}

.nuo-cal-timeline .bubble-content-inner {
    padding: 16px 18px 14px;
}

/* 時間行搬到最上面，前面加 ▷
   （「我的」頁時間外面還包了一層 div，所以搬的是欄位裡的最後一個子元素） */
.nuo-cal-timeline .bubble-content-inner > div > div > div:last-child {
    order: -1;
    margin-top: 0 !important;
    margin-bottom: 4px;
}

.nuo-cal-timeline .agenda-time {
    font-family: var(--hand);
    font-size: 0.95rem !important;
    letter-spacing: 1px;
    color: var(--sky-deep) !important;
}

/* 行內寫死的「依時長拉高」取消，塊高只跟內容走 */
.nuo-cal-timeline .timeline-bubble.modern-bubble {
    min-height: 0 !important;
}

.nuo-cal-timeline .agenda-time::before {
    content: '▷';
    margin-right: 6px;
    font-size: 0.85em;
}

.nuo-cal-timeline .bubble-title,
.nuo-cal-timeline .agenda-title {
    font-family: var(--hand);
    letter-spacing: 1px;
}

.nuo-cal-timeline .bubble-location {
    color: #7fa2ba;
}

/* 一天起訖那兩條標記 → 月亮點點分隔線 */
.nuo-cal-timeline .timeline-marker-content {
    width: 100%;
    justify-content: center;
    background: transparent;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
    color: #9fd0f0;
    font-family: var(--hand);
    letter-spacing: 2px;
    padding: 4px 0;
    border-top: 2px dotted rgba(140, 200, 240, 0.55);
    border-radius: 0;
}

.nuo-cal-timeline .timeline-marker-content::before {
    content: '☾ ';
}

.nuo-cal-timeline .timeline-marker-content::after {
    content: ' ☽';
}

/* 我的行程表：頂部資訊條變手帳頁眉 */
.nuo-cal-timeline-user .user-stat-header {
    padding-bottom: 8px;
}

.nuo-cal-timeline-user .stat-name {
    font-family: var(--hand);
    font-size: 1.4rem;
    letter-spacing: 1px;
}

/* 待辦面板：加四角括弧相框 */
.nuo-cal-timeline .todo-section-card {
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border-top: 1px solid rgba(255, 255, 255, 0.9);
}

.nuo-cal-timeline .todo-header-row .section-title {
    font-size: 1.25rem;
}

.nuo-cal-timeline .todo-card {
    background: rgba(226, 243, 255, 0.6);
    border: 1px solid rgba(255, 255, 255, 0.85);
    box-shadow: 0 0 16px var(--glow);
}

/* 頁面頂部裝飾：星星 */
.nuo-cal-decor-chars-top,
.nuo-cal-decor-mine-top {
    display: block;
    position: absolute;
    right: 22px;
    top: calc(var(--nuo-safe-top, 0px) + 18px);
    font-size: 1.6rem;
    color: #9fd0f0;
    pointer-events: none;
    z-index: 3;
}

.nuo-cal-decor-chars-top::before,
.nuo-cal-decor-mine-top::before {
    content: '✦';
}

/* ================= 共鳴影集：手帳相簿頁（整頁重排） ================= */
/* 頁眉：標題改成左上大號手寫淺藍，不再是圓角章 */
.nuo-cal-memory .memory-header {
    justify-content: flex-start !important;
    padding-bottom: 4px;
}

.nuo-cal-memory .memory-title {
    background: transparent;
    border: none;
    box-shadow: none;
    transform: none;
    padding: 0;
    font-family: var(--hand);
    font-size: 2.4rem;
    font-weight: 300;
    letter-spacing: 3px;
    color: #b7dcf3;
}

.nuo-cal-memory .memory-scroll-content {
    padding-bottom: 130px;
}

/* 每個分區都變成一塊發光藍手帳卡 */
.nuo-cal-memory .memory-section,
.nuo-cal-memory .mochi-report-card {
    position: relative;
    background: rgba(226, 243, 255, 0.55);
    border: 1px solid rgba(255, 255, 255, 0.9);
    border-radius: 20px;
    padding: 18px 16px 16px;
    margin-bottom: 26px;
    box-shadow: 0 0 0 8px rgba(200, 230, 255, 0.4), 0 12px 30px rgba(120, 175, 215, 0.18);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
}

/* 四角小括弧 */
.nuo-cal-memory .memory-section::before,
.nuo-cal-memory .mochi-report-card::before {
    content: '';
    position: absolute;
    inset: 7px;
    pointer-events: none;
    border-radius: 14px;
    background:
        radial-gradient(circle at 0 0, transparent 9px, rgba(140, 200, 240, 0.6) 10px, transparent 12px) top left / 22px 22px no-repeat,
        radial-gradient(circle at 100% 0, transparent 9px, rgba(140, 200, 240, 0.6) 10px, transparent 12px) top right / 22px 22px no-repeat,
        radial-gradient(circle at 0 100%, transparent 9px, rgba(140, 200, 240, 0.6) 10px, transparent 12px) bottom left / 22px 22px no-repeat,
        radial-gradient(circle at 100% 100%, transparent 9px, rgba(140, 200, 240, 0.6) 10px, transparent 12px) bottom right / 22px 22px no-repeat;
}

/* 分區標題：▷ 手寫藍字 + 下方月亮點點線 */
.nuo-cal-memory .section-title,
.nuo-cal-memory .report-header {
    font-family: var(--hand);
    font-weight: 400;
    font-size: 1.25rem;
    letter-spacing: 2px;
    color: var(--sky-deep);
    margin-bottom: 14px;
    padding-bottom: 8px;
    border-bottom: 2px dotted rgba(140, 200, 240, 0.55);
    justify-content: flex-start;
}

.nuo-cal-memory .section-title::before,
.nuo-cal-memory .report-header::before {
    content: '▷';
    font-size: 0.85em;
    margin-right: 4px;
}

.nuo-cal-memory .section-icon-img,
.nuo-cal-memory .report-sparkle {
    color: #9fd0f0;
}

/* 月報：光環改藍、文字改藍 */
.nuo-cal-memory .mochi-glow-ring {
    background: radial-gradient(circle, rgba(220, 240, 255, 1) 0%, rgba(220, 240, 255, 0) 70%);
}

.nuo-cal-memory .satisfaction-title {
    font-family: var(--hand);
    letter-spacing: 1px;
    color: var(--ink-blue);
}

.nuo-cal-memory .satisfaction-desc {
    color: #7fa2ba;
    font-family: var(--hand);
}

/* 拍立得：白框 + 藍紙膠帶 + 手寫說明 */
.nuo-cal-memory .polaroid-item {
    box-shadow: 0 8px 22px rgba(120, 175, 215, 0.25);
}

.nuo-cal-memory .tape-strip {
    background: rgba(170, 215, 245, 0.8);
    background-image: repeating-linear-gradient(-45deg, rgba(255, 255, 255, 0.55) 0 4px, transparent 4px 8px);
}

.nuo-cal-memory .polaroid-caption {
    letter-spacing: 1px;
}

.nuo-cal-memory .caption-date {
    color: #9fd0f0;
}

/* 成就：貼紙冊——虛線格 + 白底 */
.nuo-cal-memory .achievement-list-grid {
    background: rgba(255, 255, 255, 0.55);
    border: 2px dashed rgba(140, 200, 240, 0.6);
    border-radius: 14px;
    padding: 14px 8px;
}

.nuo-cal-memory .achievement-item {
    filter: drop-shadow(0 6px 14px rgba(120, 175, 215, 0.25));
}

.nuo-cal-memory .badge-name {
    font-family: var(--hand);
}

/* 信件：藍虛線相紙 */
.nuo-cal-memory .message-letter-paper {
    border: 2px dashed rgba(140, 200, 240, 0.6);
    border-radius: 8px;
    box-shadow: 0 0 18px var(--glow);
}

.nuo-cal-memory .letter-content,
.nuo-cal-memory .signer-name {
    font-family: var(--hand);
    color: #4d6d86;
}

.nuo-cal-decor-memory-top {
    display: block;
    position: absolute;
    right: 22px;
    top: calc(var(--nuo-safe-top, 0px) + 18px);
    font-size: 1.6rem;
    color: #9fd0f0;
    pointer-events: none;
    z-index: 3;
}

.nuo-cal-decor-memory-top::before {
    content: '✦';
}

/* ================= 行程塊重排（照圖二：時間在頂、左側小圖、備註做成便條） ================= */
.nuo-cal-timeline .timeline-bubble.modern-bubble {
    border-radius: 20px;
    background-color: rgba(206, 234, 255, 0.7);
    background-image: linear-gradient(180deg, rgba(255, 255, 255, 0.55), rgba(255, 255, 255, 0.05));
    box-shadow: 0 0 0 6px rgba(206, 234, 255, 0.45), 0 0 0 12px rgba(206, 234, 255, 0.18), 0 10px 26px rgba(120, 175, 215, 0.2);
    margin: 10px 4px;
}

.nuo-cal-timeline .bubble-content-inner {
    padding: 14px 16px 12px 16px;
}

/* 左側小圖：有圖用圖，沒圖用內建線條星星 */
.nuo-cal-timeline .bubble-content-inner > div:first-child {
    position: relative;
    padding-left: 64px;
    min-height: 56px;
}

.nuo-cal-timeline .bubble-content-inner > div:first-child::before {
    content: '';
    position: absolute;
    left: 0;
    top: 22px;
    width: 52px;
    height: 52px;
    border-radius: 12px;
    background:
        var(--art-event-icon) center / cover no-repeat,
        url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%236bb2df' stroke-width='1.6' stroke-linejoin='round'><path d='M12 3.5l1.9 5.6 5.6 1.9-5.6 1.9L12 18.5l-1.9-5.6-5.6-1.9 5.6-1.9z'/><circle cx='19' cy='5' r='1' fill='%23a9d8f5' stroke='none'/><circle cx='5' cy='19' r='1' fill='%23a9d8f5' stroke='none'/></svg>") center / 26px 26px no-repeat,
        var(--lattice);
    box-shadow: 0 4px 12px rgba(120, 175, 215, 0.25), inset 0 0 0 2px rgba(255, 255, 255, 0.9);
}

/* 時間行：整行從左側小圖上方拉出來 */
.nuo-cal-timeline .bubble-content-inner > div > div > div:last-child {
    margin-left: -64px;
    margin-bottom: 8px;
}

.nuo-cal-timeline .agenda-time {
    font-size: 1.05rem !important;
    letter-spacing: 1.5px;
}

/* 標題大一號、地點換圖標 */
.nuo-cal-timeline .bubble-title {
    font-size: 1.08rem !important;
    color: #3f6284 !important;
}

.nuo-cal-timeline .bubble-location {
    color: #7fa2ba !important;
    font-family: var(--hand);
}

.nuo-cal-timeline .bubble-location > svg {
    color: #8ecbf0;
    stroke-width: 2.2;
}

/* 備註：從右下斜體灰字改成左側白色便條 */
.nuo-cal-timeline .nuo-cal-note {
    text-align: left !important;
    font-style: normal !important;
    font-family: var(--hand);
    color: #6d90ab !important;
    background: rgba(255, 255, 255, 0.7);
    border-top: none !important;
    border-left: 3px solid rgba(140, 200, 240, 0.8);
    border-radius: 0 10px 10px 0;
    padding: 6px 10px !important;
    margin-top: 8px !important;
}

.nuo-cal-timeline .nuo-cal-note::before {
    content: '✎ ';
    opacity: 0.7;
}

/* 日期標題：三角旗換成圖標 */
.nuo-cal-timeline .timeline-flag-icon svg path {
    fill: #8ecbf0;
}

.nuo-cal-timeline .timeline-flag-icon {
    margin-left: 0 !important;
}

/* 「現在」膠囊：靠左貼齊內容，不再壓到邊 */
.nuo-cal-timeline .timeline-current-time-indicator {
    margin-left: 0 !important;
}

/* 待辦標題圖標 */
.nuo-cal-timeline .todo-header-row .section-icon {
    font-size: 0;
    text-indent: -9999px;
    overflow: hidden;
    white-space: nowrap;
    width: 22px;
    height: 22px;
    display: inline-block;
    vertical-align: middle;
    margin-right: 6px;
    background: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%236bb2df' stroke-width='1.8' stroke-linecap='round' stroke-linejoin='round'><rect x='3.5' y='4' width='17' height='16' rx='4'/><path d='M8 12.2l2.6 2.6L16.5 9'/></svg>") center / contain no-repeat;
}

/* ================= 底欄 / 加號圖標：沿用線條風，重新配色 ================= */
.nuo-cal-nav-btn > svg {
    width: 22px;
    height: 22px;
    stroke-width: 1.8;
    color: #9db9cd;
    transition: color 0.2s ease, transform 0.2s ease;
}

.nuo-cal-nav-btn.active > svg {
    color: #3f6f97;
    transform: translateY(-1px);
}

.nuo-cal-nav-btn span {
    font-family: var(--hand);
    letter-spacing: 1px;
}

.add-button > svg {
    stroke-width: 2.4;
}

