/* ============ 一、可自定义区（只改这里） ============ */
:root {
  --paper-name: "紫藤笺";
  --letter-sub: "紫藤挂云木";
  --wait-text: "花下写信中……";
  --count-unit: "札";
  --reply-name: "回笺";
  --reply-sub: "来信收悉";
  --btn-chapter: "卷帙";
  --btn-setting: "文房";
  --user-size: 15px;
  --bloom-right-pos: 33%;
  --bloom-left-pos: 66%;
}

