/* ============ 三、样式（不用改） ============ */
#this-moment-screen { background: var(--page) !important; }
.tm-bg-image { filter: var(--bg-img-filter) !important; opacity: 0.1 !important; }
.tm-bg-overlay { background-color: var(--page) !important; background-image: var(--ink-cloud), var(--ink-hills) !important; background-repeat: no-repeat, no-repeat !important; background-position: right -30px top 40px, left 50% bottom 70px !important; background-size: 85% auto, 100% auto !important; }
.tm-header { position: relative !important; z-index: 5; background: var(--bar) !important; backdrop-filter: blur(10px) !important; -webkit-backdrop-filter: blur(10px) !important; border-bottom: none !important; box-shadow: none !important; }
.tm-header::before { content: "" !important; position: absolute !important; left: 0; right: 0; bottom: 0; height: 1px; pointer-events: none; background: linear-gradient(90deg, transparent, var(--line-strong) 18%, var(--line-strong) 82%, transparent); }
