.tm-btn-icon { color: var(--ink-soft) !important; }
.tm-header-avatar { border: 1px solid var(--line-strong) !important; border-radius: 50% !important; }
.tm-top-vs { font-size: 0 !important; color: var(--ink-soft) !important; }
.tm-top-vs::before { content: "致"; font-family: var(--song); font-size: 13px; letter-spacing: 0.1em; }
.tm-header-right .tm-btn-icon { width: auto !important; min-width: 0 !important; padding: 0 6px !important; background: transparent !important; font-family: var(--song) !important; font-size: 13px !important; letter-spacing: 0.18em !important; color: var(--ink-soft) !important; }
