.tm-para-char { position: relative !important; display: flex !important; flex-direction: column !important; overflow: visible !important; box-sizing: border-box !important; width: 92% !important; max-width: 680px !important; margin: 14px auto 18px !important; align-self: center !important; padding: 30px 26px 30px !important; border: none !important; border-radius: 2px !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; background: linear-gradient(var(--line-strong), var(--line-strong)) center 12px / calc(100% - 36px) 1px no-repeat, linear-gradient(var(--line), var(--line)) center 15px / calc(100% - 36px) 1px no-repeat, linear-gradient(var(--line), var(--line)) center calc(100% - 15px) / calc(100% - 36px) 1px no-repeat, linear-gradient(var(--line-strong), var(--line-strong)) center calc(100% - 12px) / calc(100% - 36px) 1px no-repeat, var(--paper) !important; box-shadow: var(--card-shadow) !important; }
.tm-para-char::before { content: var(--paper-name) !important; position: absolute !important; top: 26px; left: 16px; writing-mode: vertical-rl; font-family: var(--song); font-size: 10.5px; letter-spacing: 0.5em; color: var(--ink-faint); pointer-events: none; }
