.tm-para-char .tc-divider { order: -1; position: static !important; height: 12px !important; min-height: 0 !important; margin: 6px 0 12px !important; padding: 0 !important; border: none !important; background: linear-gradient(var(--line-strong), var(--line-strong)) center / 28px 1px no-repeat !important; }

.tm-para-char .tc-divider::before, .tm-para-char .tc-divider::after, .tm-para-char .tc-meta-subtitle::after { content: "" !important; position: absolute !important; z-index: 0; pointer-events: none; background: var(--accent); opacity: var(--bloom-op); filter: blur(var(--bloom-blur)); -webkit-mask: var(--bloom-mask) center / contain no-repeat; mask: var(--bloom-mask) center / contain no-repeat; }
.tm-para-char .tc-divider::before { top: 0; left: 30px; width: 96px; height: 48px; }
.tm-para-char .tc-divider::after { top: var(--bloom-right-pos); right: -16px; width: 66px; height: 33px; transform: translateY(-50%) rotate(78deg); }
.tm-para-char .tc-meta-subtitle::after { top: var(--bloom-left-pos); left: -14px; width: 60px; height: 30px; opacity: calc(var(--bloom-op) * 0.85); transform: translateY(-50%) rotate(-90deg); }

.tm-para-char .tc-meta-title, .tm-para-user .tc-meta-title-user { display: block !important; font-family: var(--song) !important; color: var(--ink) !important; font-size: 15px !important; font-weight: 500 !important; letter-spacing: 0.3em !important; }
