.tm-para-char .tc-stat[data-label="time"]::before, .tm-para-user .tc-meta-stats-user .tc-stat[data-label="time"]::before { content: "·"; margin: 0 6px; }

.tm-para-char .tc-stat[data-label="page"], .tm-para-char .tc-stat[data-label="words"] { position: absolute !important; right: 22px !important; z-index: 1; font-size: 10.5px !important; letter-spacing: 0 !important; white-space: nowrap; }
