.tm-body-char { background: transparent !important; color: var(--ink) !important; line-height: 1.95 !important; letter-spacing: 0.02em; margin: 0 !important; padding: 0 2px !important; }

.tm-para-user { position: relative !important; display: flex !important; flex-direction: column !important; overflow: visible !important; box-sizing: border-box !important; width: 84% !important; max-width: 600px !important; margin: 14px auto 18px !important; align-self: center !important; padding: 22px 22px 20px 34px !important; border: none !important; border-radius: 2px !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; background: linear-gradient(var(--line), var(--line)) center 9px / calc(100% - 28px) 1px no-repeat, linear-gradient(var(--line), var(--line)) center calc(100% - 9px) / calc(100% - 28px) 1px no-repeat, var(--paper-user) !important; box-shadow: var(--card-shadow) !important; }
.tm-para-user::before { content: var(--reply-name) !important; position: absolute !important; top: 22px; left: 14px; writing-mode: vertical-rl; font-family: var(--song); font-size: 10.5px; letter-spacing: 0.5em; color: var(--ink-faint); pointer-events: none; }
.tm-para-user::after { content: "" !important; position: absolute !important; top: -6px; right: 6px; width: 70px; height: 35px; z-index: 0; pointer-events: none; background: var(--accent); opacity: var(--bloom-op); filter: blur(var(--bloom-blur)); transform: scaleX(-1) rotate(-8deg); -webkit-mask: var(--bloom-mask) center / contain no-repeat; mask: var(--bloom-mask) center / contain no-repeat; }

.tm-para-user .tc-header-user { display: contents !important; }
.tm-para-user .tc-avatar-area, .tm-para-user .tc-meta-subtitle-user, .tm-para-user .tc-meta-extra-user, .tm-para-user .tc-divider-text-user { display: none !important; }

