.tm-para-user .tc-meta-stats-user { display: flex !important; gap: 0 !important; }
.tm-para-user .tc-meta-stats-user .tc-stat[data-label="page"], .tm-para-user .tc-meta-stats-user .tc-stat[data-label="words"] { display: none !important; }

.tm-quote { background: none !important; box-shadow: none !important; padding: 0 !important; border-radius: 0 !important; color: var(--quote) !important; font-weight: inherit !important; }
.tm-quote-block { border: none !important; background: transparent !important; box-shadow: none !important; border-radius: 0 !important; padding: 0 !important; margin-left: 0 !important; color: inherit !important; font-weight: inherit !important; }
.tm-quote-block::before, .tm-quote-block::after { content: none !important; }
.tm-action { color: var(--ink-soft) !important; font-style: normal !important; }
.tm-del { color: var(--ink-faint) !important; text-decoration-line: line-through !important; text-decoration-color: var(--line-strong) !important; text-decoration-thickness: 1px !important; }
.tm-bold { color: inherit !important; font-weight: inherit !important; background: none !important; padding: 0 !important; text-decoration: none !important; }
.tm-heading { text-align: center !important; letter-spacing: 0.3em !important; color: var(--ink) !important; font-weight: 600 !important; }

.tm-loading-container { background: transparent !important; display: flex !important; align-items: center !important; justify-content: center !important; gap: 10px !important; padding: 16px 0 !important; font-size: 0 !important; }
.tm-loading-text { display: none !important; }
.tm-loading-container::before { content: "" !important; flex: none; width: 24px; height: 24px; background: var(--accent); -webkit-mask-image: var(--m-petal-1), var(--m-petal-2), var(--m-petal-3), var(--m-petal-4), var(--m-petal-5); mask-image: var(--m-petal-1), var(--m-petal-2), var(--m-petal-3), var(--m-petal-4), var(--m-petal-5); -webkit-mask-position: center; mask-position: center; -webkit-mask-repeat: no-repeat; mask-repeat: no-repeat; -webkit-mask-size: 24px 24px; mask-size: 24px 24px; }
.tm-loading-container::after { content: var(--wait-text) !important; font-family: var(--song); font-size: 12px !important; letter-spacing: 0.35em !important; color: var(--ink-faint) !important; }
#this-moment-screen:not(.tm-no-animations) .tm-loading-container::before { animation: lfBloom 3s ease-in-out infinite; }
#this-moment-screen:not(.tm-no-animations) .tm-loading-container::after { animation: lfInk 3s ease-in-out infinite; }
@keyframes lfBloom { 0% { -webkit-mask-size: 0px 0px, 0px 0px, 0px 0px, 0px 0px, 0px 0px; mask-size: 0px 0px, 0px 0px, 0px 0px, 0px 0px, 0px 0px; opacity: 1; transform: rotate(0deg); } 10% { -webkit-mask-size: 24px 24px, 0px 0px, 0px 0px, 0px 0px, 0px 0px; mask-size: 24px 24px, 0px 0px, 0px 0px, 0px 0px, 0px 0px; } 20% { -webkit-mask-size: 24px 24px, 24px 24px, 0px 0px, 0px 0px, 0px 0px; mask-size: 24px 24px, 24px 24px, 0px 0px, 0px 0px, 0px 0px; } 30% { -webkit-mask-size: 24px 24px, 24px 24px, 24px 24px, 0px 0px, 0px 0px; mask-size: 24px 24px, 24px 24px, 24px 24px, 0px 0px, 0px 0px; } 40% { -webkit-mask-size: 24px 24px, 24px 24px, 24px 24px, 24px 24px, 0px 0px; mask-size: 24px 24px, 24px 24px, 24px 24px, 24px 24px, 0px 0px; } 50%, 80% { -webkit-mask-size: 24px 24px, 24px 24px, 24px 24px, 24px 24px, 24px 24px; mask-size: 24px 24px, 24px 24px, 24px 24px, 24px 24px, 24px 24px; opacity: 1; } 100% { -webkit-mask-size: 24px 24px, 24px 24px, 24px 24px, 24px 24px, 24px 24px; mask-size: 24px 24px, 24px 24px, 24px 24px, 24px 24px, 24px 24px; opacity: 0; transform: rotate(24deg); } }
@keyframes lfInk { 0%, 100% { opacity: 0.45; } 50% { opacity: 1; } }
.tm-stream-cursor { background: var(--accent-deep) !important; width: 1.5px !important; }

.tm-compose { background: var(--bar) !important; backdrop-filter: blur(10px) !important; -webkit-backdrop-filter: blur(10px) !important; border-top: 1px solid var(--line) !important; box-shadow: none !important; padding: 4px 14px calc(8px + var(--nuo-safe-bottom, 0px)) !important; }
.tm-compose-toolbar { padding: 0 !important; margin: 0 0 2px !important; min-height: 0 !important; gap: 2px !important; border: none !important; background: transparent !important; }
.tm-regen-btn, .tm-suggestions-btn { height: 26px !important; min-height: 0 !important; padding: 0 7px !important; background: transparent !important; border: none !important; box-shadow: none !important; border-radius: 999px !important; color: var(--ink-faint) !important; font-size: 11px !important; }
.tm-regen-btn svg, .tm-suggestions-btn svg { width: 15px !important; height: 15px !important; }
.tm-regen-btn:active, .tm-suggestions-btn:active { color: var(--ink) !important; }
.tm-regen-btn.active, .tm-suggestions-btn.active { color: var(--accent-deep) !important; background: var(--line) !important; }
.tm-bond-glyph { font-size: 13px !important; filter: grayscale(0.4); }

.tm-compose-row { gap: 8px !important; padding: 0 !important; align-items: center !important; }
.tm-input { background: transparent !important; border: none !important; border-bottom: 1px solid var(--line-strong) !important; border-radius: 0 !important; box-shadow: none !important; padding: 8px 2px 6px !important; min-height: 38px !important; font-size: 16px !important; line-height: 1.5 !important; color: var(--ink) !important; caret-color: var(--accent-deep) !important; }
.tm-input:placeholder-shown { height: 38px !important; }
.tm-input:focus { border-bottom-color: var(--ink-soft) !important; outline: none !important; box-shadow: none !important; }
.tm-input::placeholder { color: var(--ink-faint) !important; letter-spacing: 0.1em; }

.tm-send-btn { flex: none !important; width: 32px !important; height: 32px !important; min-width: 32px !important; padding: 0 !important; display: flex !important; align-items: center !important; justify-content: center !important; border: none !important; border-radius: 0 !important; background: transparent !important; box-shadow: none !important; color: var(--ink-faint) !important; }
.tm-send-btn.ready { color: var(--ink-deep) !important; background: transparent !important; }
.tm-send-btn:not(.tm-stop-btn) svg { display: none !important; }
.tm-send-btn:not(.tm-stop-btn)::before { content: "" !important; width: 22px; height: 22px; background: currentColor; -webkit-mask: var(--m-envelope) center / contain no-repeat; mask: var(--m-envelope) center / contain no-repeat; }
.tm-send-btn.tm-stop-btn { background: transparent !important; border: none !important; color: var(--seal) !important; }

.tm-suggestions-panel { background: transparent !important; border: none !important; }
