.tm-translation-section { border-left: none !important; padding-left: 0 !important; border-top: 1px dashed var(--line) !important; padding-top: 6px !important; }
.tm-translation-label { color: var(--ink-faint) !important; letter-spacing: 0.2em !important; }
.tm-translation-body { color: var(--ink-soft) !important; }
.tm-cg-wrapper { background: var(--cg-bg) !important; padding: 6px !important; box-shadow: var(--card-shadow) !important; }
.tm-cg-image { border-radius: 0 !important; }

.tm-time-jump-line { background: var(--line-strong) !important; }
.tm-time-jump-pill { background: transparent !important; border: 1px solid var(--line-strong) !important; color: var(--ink-soft) !important; letter-spacing: 0.2em; }
