.tm-story::-webkit-scrollbar { width: 3px !important; }
.tm-story::-webkit-scrollbar-thumb { background: var(--line-strong) !important; border-radius: 3px !important; }
.tm-story::-webkit-scrollbar-track { background: transparent !important; }
.tm-context-menu { background: var(--paper) !important; border: 1px solid var(--line) !important; border-radius: 6px !important; box-shadow: var(--menu-shadow) !important; }
